import { useEffect, useState } from 'react'
import './App.css'

function App() {
  const [scrollY, setScrollY] = useState(0);

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const features = [
    {
      icon: '⚡',
      title: 'Lightning Fast',
      description: 'Optimized performance with cutting-edge technology for blazing speed.'
    },
    {
      icon: '🎨',
      title: 'Beautiful Design',
      description: 'Stunning visuals crafted with attention to every pixel and detail.'
    },
    {
      icon: '🚀',
      title: 'Easy to Use',
      description: 'Intuitive interface that makes complex tasks simple and enjoyable.'
    }
  ];

  return (
    <div className="App">
      {/* Hero Section */}
      <section className="hero">
        <div className="stars"></div>
        <div className="stars2"></div>
        <div className="stars3"></div>

        <div className="hero-content" style={{ transform: `translateY(${scrollY * 0.5}px)` }}>
          <h1 className="hero-title">
            Welcome to the
            <span className="gradient-text"> Future</span>
          </h1>
          <p className="hero-subtitle">
            Experience the next generation of digital innovation with stunning design and powerful features
          </p>
          <button className="cta-button">
            <span>Get Started</span>
            <div className="glow"></div>
          </button>
        </div>

        <div className="scroll-indicator">
          <div className="mouse">
            <div className="wheel"></div>
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section className="features">
        <h2 className="section-title">Why Choose Us</h2>
        <div className="features-grid">
          {features.map((feature, index) => (
            <div 
              key={index} 
              className="feature-card"
              style={{ 
                animationDelay: `${index * 0.2}s`,
                transform: scrollY > 200 ? 'translateY(0) scale(1)' : 'translateY(50px) scale(0.9)',
                opacity: scrollY > 200 ? 1 : 0,
                transition: `all 0.6s ease ${index * 0.1}s`
              }}
            >
              <div className="feature-icon">{feature.icon}</div>
              <h3 className="feature-title">{feature.title}</h3>
              <p className="feature-description">{feature.description}</p>
              <div className="feature-glow"></div>
            </div>
          ))}
        </div>
      </section>

      {/* Footer */}
      <footer className="footer">
        <p>© 2024 Beautiful Landing. Crafted with passion.</p>
      </footer>
    </div>
  )
}

export default App

/* Root Variables */
:root {
  --primary-gradient: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  --secondary-gradient: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
  --dark-bg: #0f0f1a;
  --darker-bg: #08080f;
  --card-bg: rgba(26, 26, 46, 0.8);
  --text-primary: #ffffff;
  --text-secondary: #a0a0c0;
  --accent-purple: #667eea;
  --accent-pink: #f5576c;
  --glow-color: rgba(102, 126, 234, 0.5);
  --spacing-unit: 8px;
  --border-radius: 16px;
  --transition-smooth: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Global Styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: var(--dark-bg);
  color: var(--text-primary);
  overflow-x: hidden;
}

/* App Container */
.App {
  min-height: 100vh;
  background: linear-gradient(135deg, #0f0f1a 0%, #1a1a2e 50%, #16213e 100%);
  position: relative;
  overflow: hidden;
}

/* Animated Background Elements */
.App::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle at 50% 50%, rgba(102, 126, 234, 0.1) 0%, transparent 50%);
  animation: rotate 20s linear infinite;
  z-index: 0;
}

.App::after {
  content: '';
  position: absolute;
  bottom: -50%;
  right: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle at 50% 50%, rgba(245, 87, 108, 0.1) 0%, transparent 50%);
  animation: rotate 25s linear infinite reverse;
  z-index: 0;
}

@keyframes rotate {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* Hero Section */
.hero-section {
  position: relative;
  z-index: 1;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: calc(var(--spacing-unit) * 10) calc(var(--spacing-unit) * 4);
  text-align: center;
}

.hero-title {
  font-size: clamp(3rem, 8vw, 6rem);
  font-weight: 800;
  background: var(--primary-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: calc(var(--spacing-unit) * 3);
  animation: fadeInUp 1s ease-out;
  letter-spacing: -2px;
  line-height: 1.1;
}

.hero-subtitle {
  font-size: clamp(1.2rem, 3vw, 1.8rem);
  color: var(--text-secondary);
  margin-bottom: calc(var(--spacing-unit) * 6);
  max-width: 700px;
  animation: fadeInUp 1s ease-out 0.2s backwards;
  line-height: 1.6;
  font-weight: 300;
}

/* CTA Button */
.cta-button {
  position: relative;
  padding: calc(var(--spacing-unit) * 2.5) calc(var(--spacing-unit) * 6);
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--primary-gradient);
  border: none;
  border-radius: calc(var(--border-radius) / 2);
  cursor: pointer;
  transition: var(--transition-smooth);
  animation: fadeInUp 1s ease-out 0.4s backwards;
  overflow: hidden;
  box-shadow: 0 8px 32px rgba(102, 126, 234, 0.3);
}

.cta-button::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #764ba2 0%, #667eea 100%);
  opacity: 0;
  transition: var(--transition-smooth);
  z-index: -1;
}

.cta-button:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 48px rgba(102, 126, 234, 0.5);
}

.cta-button:hover::before {
  opacity: 1;
}

.cta-button:active {
  transform: translateY(-2px);
}

/* Glow Effect */
.cta-button::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  transform: translate(-50%, -50%);
  transition: width 0.6s, height 0.6s;
}

.cta-button:hover::after {
  width: 300px;
  height: 300px;
  opacity: 0;
}

/* Features Section */
.features-section {
  position: relative;
  z-index: 1;
  padding: calc(var(--spacing-unit) * 15) calc(var(--spacing-unit) * 4);
  max-width: 1400px;
  margin: 0 auto;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: calc(var(--spacing-unit) * 4);
  margin-top: calc(var(--spacing-unit) * 8);
}

/* Feature Cards */
.feature-card {
  background: var(--card-bg);
  border: 1px solid rgba(102, 126, 234, 0.2);
  border-radius: var(--border-radius);
  padding: calc(var(--spacing-unit) * 5);
  transition: var(--transition-smooth);
  backdrop-filter: blur(10px);
  position: relative;
  overflow: hidden;
  animation: fadeInUp 1s ease-out;
}

.feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(102, 126, 234, 0.1) 0%, rgba(245, 87, 108, 0.1) 100%);
  opacity: 0;
  transition: var(--transition-smooth);
  z-index: -1;
}

.feature-card:hover {
  transform: translateY(-12px);
  border-color: rgba(102, 126, 234, 0.5);
  box-shadow: 0 20px 60px rgba(102, 126, 234, 0.3);
}

.feature-card:hover::before {
  opacity: 1;
}

.feature-card:nth-child(1) {
  animation-delay: 0.1s;
}

.feature-card:nth-child(2) {
  animation-delay: 0.2s;
}

.feature-card:nth-child(3) {
  animation-delay: 0.3s;
}

/* Feature Icons */
.feature-icon {
  width: 80px;
  height: 80px;
  margin: 0 auto calc(var(--spacing-unit) * 3);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  background: var(--primary-gradient);
  border-radius: 20px;
  box-shadow: 0 8px 24px rgba(102, 126, 234, 0.3);
  transition: var(--transition-smooth);
}

.feature-card:hover .feature-icon {
  transform: scale(1.1) rotate(5deg);
  box-shadow: 0 12px 32px rgba(102, 126, 234, 0.5);
}

.feature-title {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: calc(var(--spacing-unit) * 2);
  color: var(--text-primary);
  text-align: center;
}

.feature-description {
  font-size: 1.1rem;
  color: var(--text-secondary);
  line-height: 1.7;
  text-align: center;
  font-weight: 300;
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
}

/* Scroll Reveal Animation */
.scroll-reveal {
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 0.8s ease-out, transform 0.8s ease-out;
}

.scroll-reveal.revealed {
  opacity: 1;
  transform: translateY(0);
}

/* Responsive Design */
@media (max-width: 768px) {
  .hero-section {
    padding: calc(var(--spacing-unit) * 8) calc(var(--spacing-unit) * 3);
  }

  .hero-title {
    font-size: 3rem;
  }

  .hero-subtitle {
    font-size: 1.2rem;
  }

  .cta-button {
    padding: calc(var(--spacing-unit) * 2) calc(var(--spacing-unit) * 4);
    font-size: 1rem;
  }

  .features-grid {
    grid-template-columns: 1fr;
    gap: calc(var(--spacing-unit) * 3);
  }

  .features-section {
    padding: calc(var(--spacing-unit) * 8) calc(var(--spacing-unit) * 3);
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: 2.5rem;
  }

  .hero-subtitle {
    font-size: 1rem;
  }

  .feature-card {
    padding: calc(var(--spacing-unit) * 4);
  }

  .feature-icon {
    width: 64px;
    height: 64px;
    font-size: 2rem;
  }

  .feature-title {
    font-size: 1.5rem;
  }

  .feature-description {
    font-size: 1rem;
  }
}

/* Additional Polish */
::selection {
  background: rgba(102, 126, 234, 0.3);
  color: var(--text-primary);
}

::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: var(--darker-bg);
}

::-webkit-scrollbar-thumb {
  background: var(--primary-gradient);
  border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(135deg, #764ba2 0%, #667eea 100%);
}

